package no.ntnuf.gliderlog.common

import java.io.Serializable
import java.text.SimpleDateFormat
import java.util.ArrayList
import java.util.Date

class DayLog : Serializable {
    companion object {
        private const val serialVersionUID: Long = 8L
        const val dayLogFileName: String = "gliderlog_"
    }

    var headOfOperations: Contact? = null
    var airfield: String? = null
    var date: Date = Date()
    var flights: ArrayList<FlightEntry> = ArrayList()

    var logIsLocked: Boolean = false
    private var logHasBeenSent: Boolean = false
    private var logSentNumberOfTimes: Int = 0

    fun getFilename(): String {
        val outdf = SimpleDateFormat("yyyy_MM_dd")
        val daylogsuffix = outdf.format(date)
        return dayLogFileName + daylogsuffix
    }

    fun setLogHasBeenSent() {
        logHasBeenSent = true
        logIsLocked = true
        logSentNumberOfTimes += 1
    }

    fun sortOnTakeoff() {
        flights.sortWith(compareBy<FlightEntry> { it.takeoff == null }.thenBy { it.takeoff })
    }

    fun isLogComplete(): Boolean {
        for (flight in flights) {
            if (flight.takeoff == null || flight.towRelease == null || flight.landing == null) {
                return false
            }
            if (flight.status != FlightStatus.LANDED) {
                return false
            }
        }
        return true
    }

    fun deleteLogLine(line: Int) {
        if (line in flights.indices) {
            flights.removeAt(line)
        }
    }
}

package no.ntnuf.gliderlog.common

import java.io.Serializable
import java.text.SimpleDateFormat
import java.util.ArrayList
import java.util.Date
import java.util.Locale

class DayLog : Serializable {
    companion object {
        private const val serialVersionUID: Long = 8L
        const val dayLogFileName: String = "gliderlog_"
    }

    var headOfOperations: Contact? = null
    var airfield: String? = null
    var date: Date = Date()
    var flights: ArrayList<FlightEntry> = ArrayList()

    var logIsLocked: Boolean = false
    private var logHasBeenSent: Boolean = false
    private var logSentNumberOfTimes: Int = 0

    fun getFilename(): String {
        val outdf = SimpleDateFormat("yyyy_MM_dd", Locale.ENGLISH)
        val daylogsuffix = outdf.format(date)
        return dayLogFileName + daylogsuffix
    }

    fun setLogHasBeenSent() {
        logHasBeenSent = true
        logIsLocked = true
        logSentNumberOfTimes += 1
    }

    fun sortOnTakeoff() {
        flights.sortWith(compareBy<FlightEntry> { it.takeoff == null }.thenBy { it.takeoff })
    }

    fun isLogComplete(): Boolean {
        for (flight in flights) {
            if (flight.takeoff == null || flight.towRelease == null || flight.landing == null) {
                return false
            }
            if (flight.status != FlightStatus.LANDED) {
                return false
            }
        }
        return true
    }

    fun deleteLogLine(line: Int) {
        if (line in flights.indices) {
            flights.removeAt(line)
        }
    }

    fun getMarkdownOutput(roundToNearest: Int): String {
        val outdf = SimpleDateFormat("EEEE yyyy-MM-dd", Locale.ENGLISH)
        val hourmin = SimpleDateFormat("HH:mm", Locale.ENGLISH)

        val ret = StringBuilder()
        ret.append("Glider Log\n")
        ret.append("=======\n\n")
        ret.append(outdf.format(date)).append("\n")
        ret.append("-------\n\n")

        ret.append("Head of Operations:\n  ").append(headOfOperations?.name.orEmpty()).append("\n\n")
        ret.append("Airfield:\n  ").append(airfield.orEmpty()).append("\n\n")

        ret.append("Flights\n")
        ret.append("-------\n\n")

        var n = 1
        for (flight in flights) {
            ret.append(n).append(". ").append(flight.registration).append("\n")
            ret.append("   ").append(flight.pilot?.name.orEmpty()).append(" (")
                .append(flight.pilotType).append(")")
            if (flight.copilot != null) {
                ret.append(", ").append(flight.copilot?.name.orEmpty()).append(" (")
                    .append(flight.copilotType).append(")")
            }
            ret.append("\n")

            ret.append("   Takeoff ").append(formatTime(hourmin, flight.takeoff))
            ret.append(", Tow Release ").append(formatTime(hourmin, flight.towRelease))
            ret.append(", Landing ").append(formatTime(hourmin, flight.landing)).append("\n")

            ret.append("   Tow Duration ").append(flight.getTowDurationStr())
            ret.append(", Flight Duration ").append(flight.getFlightDurationStr()).append("\n")

            if (flight.notes.isNotBlank()) {
                ret.append("   ").append(flight.notes).append("\n")
            }
            n += 1
        }

        val flightTimeList = FlightTimeList()
        for (flight in flights) {
            flightTimeList.add(flight)
        }
        flightTimeList.round(roundToNearest)

        ret.append("\nPlane Summary\n")
        ret.append("-------\n\n")
        ret.append("Summary durations rounded to nearest ").append(roundToNearest).append("m\n\n")
        for ((key, value) in flightTimeList.sortedPlaneSums()) {
            ret.append("* ").append(key.registration).append("\n")
            ret.append("  Flights: ").append(value.flights).append("\n")
            ret.append("  Flight Duration ").append(minutesToDurationStr(value.flightMinutes)).append("\n")
        }

        ret.append("\nPilot Summary\n")
        ret.append("-------\n")
        ret.append("Summary durations rounded to nearest ").append(roundToNearest).append("m\n\n")
        for ((key, value) in flightTimeList.sortedPilotSums()) {
            ret.append("* ").append(key.name.orEmpty()).append(", ")
                .append(key.role).append(" ").append(key.registration).append("\n")
            ret.append("  Flights: ").append(value.flights).append("\n")
            ret.append("  Tow Duration ").append(minutesToDurationStr(value.towMinutes))
            ret.append(", Flight Duration ").append(minutesToDurationStr(value.flightMinutes)).append("\n")
        }

        if (logHasBeenSent) {
            ret.append("\nNote\n-------\n")
            ret.append("Log previously sent ").append(logSentNumberOfTimes)
                .append(" time").append(if (logSentNumberOfTimes > 1) "s" else "").append(".")
        }

        return ret.toString()
    }

    fun getHTMLtableoutput(roundToNearest: Int): String {
        val outdf = SimpleDateFormat("EEEE yyyy-MM-dd", Locale.ENGLISH)
        val hourmin = SimpleDateFormat("HH:mm", Locale.ENGLISH)
        val ret = StringBuilder()

        ret.append("<html><head><meta charset=\"UTF-8\"></head><body>")
        ret.append("<h1>Glider Log</h1>")
        ret.append("<h2>").append(outdf.format(date)).append("</h2>")
        ret.append("<p>Head of Operations:<br/>&nbsp;&nbsp;").append(headOfOperations?.name.orEmpty()).append("</p>")
        ret.append("<p>Airfield:<br/>&nbsp;&nbsp;").append(airfield.orEmpty()).append("</p>")

        ret.append("<h2>Flights</h2><table border=\"1\" cellspacing=\"0\" cellpadding=\"5\">")
        ret.append("<tr><th>#</th><th>Registration</th><th>PIC / Instructor</th><th>Student / Passenger</th><th>Takeoff</th><th>Release</th><th>Landing</th></tr>")
        ret.append("<tr><th></th><th colspan=\"4\">Notes</th><th>Tow Duration</th><th>Flight Duration</th></tr>")

        var c = 0
        for (flight in flights) {
            c += 1
            ret.append("<tr>")
            ret.append("<td>").append(c).append("</td>")
            ret.append("<td>").append(flight.registration).append("</td>")
            ret.append("<td>").append(flight.pilot?.name.orEmpty()).append(" (").append(flight.pilotType).append(")</td>")
            ret.append("<td>")
            if (flight.copilot != null) {
                ret.append(flight.copilot?.name.orEmpty()).append(" (").append(flight.copilotType).append(")")
            }
            ret.append("</td>")
            ret.append("<td>").append(formatTime(hourmin, flight.takeoff)).append("</td>")
            ret.append("<td>").append(formatTime(hourmin, flight.towRelease)).append("</td>")
            ret.append("<td>").append(formatTime(hourmin, flight.landing)).append("</td>")
            ret.append("</tr>")

            ret.append("<tr>")
            ret.append("<td></td><td colspan=\"4\">").append(flight.notes).append("</td>")
            ret.append("<td>").append(flight.getTowDurationStr()).append("</td>")
            ret.append("<td>").append(flight.getFlightDurationStr()).append("</td>")
            ret.append("</tr>")
        }
        ret.append("</table>")

        val flightTimeList = FlightTimeList()
        for (flight in flights) {
            flightTimeList.add(flight)
        }
        flightTimeList.round(roundToNearest)

        ret.append("<h2>Plane Summary</h2>")
        ret.append("<p>Summary durations rounded to nearest ").append(roundToNearest).append("m</p>")
        ret.append("<table border=\"1\" cellspacing=\"0\" cellpadding=\"5\">")
        ret.append("<tr><th>Registration</th><th>Flights</th><th>Flight Duration</th></tr>")
        for ((key, value) in flightTimeList.sortedPlaneSums()) {
            ret.append("<tr><td>").append(key.registration).append("</td><td>")
                .append(value.flights).append("</td><td>")
                .append(minutesToDurationStr(value.flightMinutes)).append("</td></tr>")
        }
        ret.append("</table>")

        ret.append("<h2>Pilot Summary</h2>")
        ret.append("<p>Summary durations rounded to nearest ").append(roundToNearest).append("m</p>")
        ret.append("<table border=\"1\" cellspacing=\"0\" cellpadding=\"5\">")
        ret.append("<tr><th>Name</th><th>Role</th><th>Registration</th><th>Flights</th><th>Tow Duration</th><th>Flight Duration</th></tr>")
        for ((key, value) in flightTimeList.sortedPilotSums()) {
            ret.append("<tr><td>").append(key.name.orEmpty()).append("</td><td>")
                .append(key.role).append("</td><td>")
                .append(key.registration).append("</td><td>")
                .append(value.flights).append("</td><td>")
                .append(minutesToDurationStr(value.towMinutes)).append("</td><td>")
                .append(minutesToDurationStr(value.flightMinutes)).append("</td></tr>")
        }
        ret.append("</table>")

        if (logHasBeenSent) {
            ret.append("<h2>Note</h2><p>Log previously sent ").append(logSentNumberOfTimes)
                .append(" time").append(if (logSentNumberOfTimes > 1) "s" else "")
                .append(".</p>")
        }

        ret.append("</body></html>")
        return ret.toString()
    }

    fun getJSONOutput(): String {
        val outdf = SimpleDateFormat("yyyy-MM-dd", Locale.ENGLISH)
        val time = SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss", Locale.ENGLISH)
        val ret = StringBuilder()

        ret.append("{\n")
        ret.append("\"headOfOperations\": \"").append(headOfOperations?.name.orEmpty()).append("\",\n")
        ret.append("\"airfield\": \"").append(airfield.orEmpty()).append("\",\n")
        ret.append("\"date\": \"").append(outdf.format(date)).append("\",\n")
        ret.append("\"sent_times\": \"").append(logSentNumberOfTimes).append("\",\n")
        ret.append("\"flights\": [\n")

        for ((index, flight) in flights.withIndex()) {
            if (index > 0) ret.append(",\n")
            ret.append(" {\n")
            ret.append("  \"flightnum\": ").append(index + 1).append(",\n")
            ret.append("  \"registration\": \"").append(flight.registration).append("\",\n")
            ret.append("  \"pilot\": \"").append(flight.pilot?.name.orEmpty()).append("\",\n")
            ret.append("  \"pilotRole\": \"").append(flight.pilotType).append("\",\n")
            ret.append("  \"takeoff\": \"").append(formatTime(time, flight.takeoff)).append("\",\n")
            ret.append("  \"tow_release\": \"").append(formatTime(time, flight.towRelease)).append("\",\n")
            ret.append("  \"landing\": \"").append(formatTime(time, flight.landing)).append("\",\n")
            ret.append("  \"towDuration\": \"").append(flight.getTowDurationStr()).append("\",\n")
            ret.append("  \"flightDuration\": \"").append(flight.getFlightDurationStr()).append("\",\n")
            ret.append("  \"notes\": \"").append(flight.notes.replace("\"", "\\\"")).append("\"\n")
            ret.append(" }")
        }

        ret.append("\n]\n}")
        return ret.toString()
    }

    private fun formatTime(format: SimpleDateFormat, value: Date?): String {
        return if (value == null) "" else format.format(value)
    }

    private fun minutesToDurationStr(minutes: Long): String {
        val hours = minutes / 60
        val minutesInHour = minutes % 60
        return "${hours}h ${minutesInHour}m"
    }
}

package no.ntnuf.gliderlog.common

class FlightTime {
    var landed: Boolean = true
    var flights: Int = 0
    var flightMinutes: Long = 0
    var studentMinutes: Long = 0
    var instructorMinutes: Long = 0
    var towMinutes: Long = 0

    private fun round(value: Long, roundToNearest: Long): Long {
        val isOdd = roundToNearest % 2L == 1L
        var roundUpIfGteq = roundToNearest / 2L
        if (isOdd) {
            roundUpIfGteq += 1L
        }

        val remainder = value % roundToNearest
        var rounded = value / roundToNearest
        if (remainder >= roundUpIfGteq) {
            rounded += 1L
        }
        return rounded * roundToNearest
    }

    fun roundAll(roundToNearest: Int) {
        val step = roundToNearest.toLong()
        flightMinutes = round(flightMinutes, step)
        studentMinutes = round(studentMinutes, step)
        instructorMinutes = round(instructorMinutes, step)
        towMinutes = round(towMinutes, step)
    }
}

package no.ntnuf.gliderlog.common

class FlightTimeList {
    val pilotSums: LinkedHashMap<NameRegistrationRole, FlightTime> = linkedMapOf()
    val planeSums: LinkedHashMap<NameRegistrationRole, FlightTime> = linkedMapOf()

    fun add(flight: FlightEntry) {
        val pilotName = flight.pilot?.name ?: return
        val pilotRole = flight.pilotType ?: return

        val pilotKey = NameRegistrationRole(pilotName, flight.registration, pilotRole, false)
        val pilotTotal = pilotSums.getOrPut(pilotKey) { FlightTime() }
        updateTotals(pilotTotal, flight, pilotRole)

        val copilotName = flight.copilot?.name
        val copilotRole = flight.copilotType
        if (copilotName != null && copilotRole != null) {
            val copilotKey = NameRegistrationRole(copilotName, flight.registration, copilotRole, false)
            val copilotTotal = pilotSums.getOrPut(copilotKey) { FlightTime() }
            updateTotals(copilotTotal, flight, copilotRole)
        }

        val planeKey = NameRegistrationRole(null, flight.registration, null, true)
        val planeTotal = planeSums.getOrPut(planeKey) { FlightTime() }
        if (flight.status == FlightStatus.LANDED) {
            planeTotal.flights += 1
            planeTotal.flightMinutes += flight.getFlightDurationMinutes()
            planeTotal.towMinutes += flight.getTowDurationMinutes()
        } else {
            planeTotal.landed = false
        }
    }

    fun sortedPilotSums(): List<Pair<NameRegistrationRole, FlightTime>> {
        return pilotSums.entries
            .sortedBy { it.key.name ?: "" }
            .map { it.key to it.value }
    }

    fun sortedPlaneSums(): List<Pair<NameRegistrationRole, FlightTime>> {
        return planeSums.entries
            .sortedBy { it.key.registration }
            .map { it.key to it.value }
    }

    fun round(roundToNearest: Int) {
        pilotSums.values.forEach { it.roundAll(roundToNearest) }
        planeSums.values.forEach { it.roundAll(roundToNearest) }
    }

    private fun updateTotals(total: FlightTime, flight: FlightEntry, role: PilotType) {
        if (flight.status == FlightStatus.LANDED) {
            total.flights += 1
            total.flightMinutes += flight.getFlightDurationMinutes()
            total.towMinutes += flight.getTowDurationMinutes()
            if (role == PilotType.INSTRUCTOR) {
                total.instructorMinutes += flight.getFlightDurationMinutes()
            }
            if (role == PilotType.STUDENT) {
                total.studentMinutes += flight.getFlightDurationMinutes()
            }
        } else {
            total.landed = false
        }
    }
}

package no.ntnuf.gliderlog.common

import android.content.Context
import android.content.SharedPreferences
import android.widget.Toast
import java.io.File
import java.io.FileNotFoundException
import java.io.IOException
import java.io.ObjectInputStream
import java.io.ObjectOutputStream
import java.text.SimpleDateFormat
import java.util.Locale
import kotlin.concurrent.thread

class LogUploader(
    private val context: Context,
    private val settings: SharedPreferences,
) {
    private val filename = "pending_uploads_list"
    private var pendingUploads: PendingUploadsList = PendingUploadsList()

    init {
        if (!loadPendingUploadsList()) {
            pendingUploads = PendingUploadsList()
        }
    }

    fun addToUploadQueue(daylog: DayLog) {
        val name = daylog.getFilename()
        if (!pendingUploads.pendingFiles.contains(name)) {
            pendingUploads.pendingFiles.add(name)
            savePendingUploadsList()
        }
    }

    fun uploadPending() {
        thread {
            val completed = arrayListOf<String>()
            for (pendingName in pendingUploads.pendingFiles) {
                val dayLog = loadDayLog(pendingName) ?: continue
                if (uploadOne(dayLog)) {
                    completed.add(pendingName)
                }
            }

            if (completed.isNotEmpty()) {
                pendingUploads.pendingFiles.removeAll(completed.toSet())
                savePendingUploadsList()
            }

            val msg = if (completed.isNotEmpty()) {
                "Uploaded ${completed.size} pending day logs to webserver"
            } else {
                "No internet connection, will upload day log later"
            }
            android.os.Handler(context.mainLooper).post {
                Toast.makeText(context, msg, Toast.LENGTH_LONG).show()
            }
        }
    }

    private fun uploadOne(daylog: DayLog): Boolean {
        val dateStr = SimpleDateFormat("yyyy-MM-dd", Locale.ENGLISH).format(daylog.date)
        val tmpFile = File(context.filesDir, "tmp_daylog.json")

        return try {
            tmpFile.writeText(daylog.getJSONOutput())
            val requestUrl = settings.getString("upload_log_url", "") ?: ""
            if (requestUrl.isBlank() || requestUrl == "https://") {
                return false
            }

            val username = settings.getString("upload_log_username", null)
            val password = settings.getString("upload_log_password", null)
            val credentials = if (!username.isNullOrBlank() && !password.isNullOrBlank()) {
                "$username:$password"
            } else {
                null
            }

            val multipart = MultipartUtility(requestUrl, "UTF-8", credentials)
            multipart.addFormField("date", dateStr)
            multipart.addFilePart("logfile", tmpFile)
            multipart.finish()
            true
        } catch (_: IOException) {
            false
        }
    }

    private fun loadDayLog(fileName: String): DayLog? {
        return try {
            context.openFileInput(fileName).use { fis ->
                ObjectInputStream(fis).use { input ->
                    input.readObject() as DayLog
                }
            }
        } catch (_: ClassNotFoundException) {
            null
        } catch (_: FileNotFoundException) {
            null
        } catch (_: IOException) {
            null
        }
    }

    private fun savePendingUploadsList() {
        try {
            context.openFileOutput(filename, Context.MODE_PRIVATE).use { fos ->
                ObjectOutputStream(fos).use { out ->
                    out.writeObject(pendingUploads)
                }
            }
        } catch (_: IOException) {
            // Keep upload queue best-effort.
        }
    }

    private fun loadPendingUploadsList(): Boolean {
        return try {
            context.openFileInput(filename).use { fis ->
                ObjectInputStream(fis).use { input ->
                    pendingUploads = input.readObject() as PendingUploadsList
                }
            }
            true
        } catch (_: ClassNotFoundException) {
            false
        } catch (_: FileNotFoundException) {
            false
        } catch (_: IOException) {
            false
        }
    }
}

package no.ntnuf.gliderlog.common

import android.util.Base64
import java.io.BufferedReader
import java.io.File
import java.io.FileInputStream
import java.io.IOException
import java.io.InputStreamReader
import java.io.OutputStream
import java.io.OutputStreamWriter
import java.io.PrintWriter
import java.net.HttpURLConnection
import java.net.URL
import java.net.URLConnection

class MultipartUtility(
    requestUrl: String,
    private val charset: String,
    userCredentialsOrNull: String?,
) {
    private val boundary = "-----${System.currentTimeMillis()}----------"
    private val httpConn: HttpURLConnection
    private val outputStream: OutputStream
    private val writer: PrintWriter

    init {
        val url = URL(requestUrl)
        httpConn = (url.openConnection() as HttpURLConnection).apply {
            useCaches = false
            doOutput = true
            doInput = true
            if (userCredentialsOrNull != null) {
                setRequestProperty(
                    "Authorization",
                    "Basic ${Base64.encodeToString(userCredentialsOrNull.toByteArray(), Base64.NO_WRAP)}",
                )
            }
            setRequestProperty("Content-Type", "multipart/form-data; boundary=$boundary")
            setRequestProperty("User-Agent", "GliderLog")
        }
        outputStream = httpConn.outputStream
        writer = PrintWriter(OutputStreamWriter(outputStream, charset), true)
    }

    fun addFormField(name: String, value: String) {
        writer.append("--$boundary").append(LINE_FEED)
        writer.append("Content-Disposition: form-data; name=\"$name\"").append(LINE_FEED)
        writer.append("Content-Type: text/plain; charset=$charset").append(LINE_FEED)
        writer.append(LINE_FEED)
        writer.append(value).append(LINE_FEED)
        writer.flush()
    }

    fun addFilePart(fieldName: String, uploadFile: File) {
        val fileName = uploadFile.name
        writer.append("--$boundary").append(LINE_FEED)
        writer.append("Content-Disposition: form-data; name=\"$fieldName\"; filename=\"$fileName\"")
            .append(LINE_FEED)
        writer.append("Content-Type: ${URLConnection.guessContentTypeFromName(fileName)}")
            .append(LINE_FEED)
        writer.append("Content-Transfer-Encoding: binary").append(LINE_FEED)
        writer.append(LINE_FEED)
        writer.flush()

        FileInputStream(uploadFile).use { inputStream ->
            val buffer = ByteArray(4096)
            var bytesRead = inputStream.read(buffer)
            while (bytesRead != -1) {
                outputStream.write(buffer, 0, bytesRead)
                bytesRead = inputStream.read(buffer)
            }
            outputStream.flush()
        }

        writer.append(LINE_FEED)
        writer.flush()
    }

    @Throws(IOException::class)
    fun finish(): String {
        val response = StringBuilder()

        writer.append(LINE_FEED).flush()
        writer.append("--$boundary--").append(LINE_FEED)
        writer.close()

        val status = httpConn.responseCode
        if (status == HttpURLConnection.HTTP_OK) {
            BufferedReader(InputStreamReader(httpConn.inputStream)).use { reader ->
                var line = reader.readLine()
                while (line != null) {
                    response.append(line)
                    line = reader.readLine()
                }
            }
            httpConn.disconnect()
        } else {
            throw IOException("Server returned non-OK status: $status")
        }

        return response.toString()
    }

    companion object {
        private const val LINE_FEED = "\r\n"
    }
}

